-- Run once (seed_runs). Odisha Tier A leaders, generated by scraper/src/bihar/leaders-cli.ts from the curated
-- scraper/data/od/leaders.json and leader-profiles.json: candidacy links (never moving curated or merged
-- persons), fill-only profile fields, and the leaders/cabinet watchlists of each Odisha manifest (written once;
-- admins edit them afterwards). Persons and image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_od_leaders')
   AS seed_apply \gset
\if :seed_apply

-- Link each leader's candidacies to the best-linked person. A candidacy moves from a one-candidacy person or from a
-- person whose candidacies all belong to this leader (leaders.json is curated); never from a merge, a split or a
-- person with an admin-entered profile.
UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('528b1ec4-2239-545b-a344-3b4ea48eeb8e', '27114048-1cb2-57bf-95e5-0aa5e5b0a24a', 'ae9ea686-ec85-553c-86dc-8060be0583cb', '389b692e-6177-5b9d-a39f-e3e9546dc3ea') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('528b1ec4-2239-545b-a344-3b4ea48eeb8e', '27114048-1cb2-57bf-95e5-0aa5e5b0a24a', 'ae9ea686-ec85-553c-86dc-8060be0583cb', '389b692e-6177-5b9d-a39f-e3e9546dc3ea') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('528b1ec4-2239-545b-a344-3b4ea48eeb8e', '27114048-1cb2-57bf-95e5-0aa5e5b0a24a', 'ae9ea686-ec85-553c-86dc-8060be0583cb', '389b692e-6177-5b9d-a39f-e3e9546dc3ea') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('528b1ec4-2239-545b-a344-3b4ea48eeb8e', '27114048-1cb2-57bf-95e5-0aa5e5b0a24a', 'ae9ea686-ec85-553c-86dc-8060be0583cb', '389b692e-6177-5b9d-a39f-e3e9546dc3ea')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));
